/*
 * مِداد — Service Worker
 * Offline-first app shell. Strategy:
 *   • navigations  → network first, fall back to cached index.html
 *   • static files → cache first, refresh in background (stale-while-revalidate)
 * The worker never caches API responses because the app has no server API:
 * all legal data lives in IndexedDB, which service workers do not touch.
 */
const VERSION = 'midad-cases-v2-20261019';
const SHELL = `${VERSION}-shell`;
const RUNTIME = `${VERSION}-runtime`;

// Files generated by `npm run build:web` (see scripts/build-web.ts). The list is
// read at install time so it always matches the actual bundle hash-free names.
const FALLBACK_PRECACHE = [
  './',
  './index.html',
  './manifest.webmanifest',
  './assets/app.css',
  './assets/app.js',
  './icons/icon-192.png',
  './icons/icon-512.png',
  './icons/icon-maskable-512.png',
  './icons/apple-touch-icon.png',
  './icons/favicon-32.png',
  './icons/icon.svg',
];

async function precacheList() {
  try {
    const response = await fetch('./precache.json', { cache: 'no-store' });
    if (!response.ok) return FALLBACK_PRECACHE;
    const files = await response.json();
    if (!Array.isArray(files) || files.length === 0) return FALLBACK_PRECACHE;
    return ['./', './index.html', ...files.map((file) => `./${String(file).replace(/^\//, '')}`)];
  } catch (error) {
    return FALLBACK_PRECACHE;
  }
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL);
      const files = await precacheList();
      // addAll fails the whole install if one file is missing; add individually
      // so a single optional asset cannot break offline support.
      await Promise.all(
        files.map((url) =>
          cache.add(new Request(url, { cache: 'reload' })).catch(() => undefined),
        ),
      );
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys.filter((key) => !key.startsWith(VERSION)).map((key) => caches.delete(key)),
      );
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  const data = event.data;
  if (data && data.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(networkFirstNavigation(request));
    return;
  }

  if (url.pathname.endsWith('/sw.js')) return;

  event.respondWith(staleWhileRevalidate(request));
});

async function networkFirstNavigation(request) {
  const cache = await caches.open(SHELL);
  try {
    const response = await fetch(request);
    if (response && response.ok) cache.put('./index.html', response.clone());
    return response;
  } catch (error) {
    const cached = (await cache.match('./index.html')) || (await cache.match('./'));
    if (cached) return cached;
    return new Response(
      '<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>غير متاح دون اتصال</title><body style="font-family:system-ui;padding:32px;text-align:center"><h1>لم يُخزَّن التطبيق بعد</h1><p>افتح البرنامج مرة واحدة مع اتصال بالشبكة ليُخزَّن للعمل دون اتصال.</p></body></html>',
      { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } },
    );
  }
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(RUNTIME);
  const cached = await cache.match(request);
  const network = fetch(request)
    .then((response) => {
      if (response && response.ok) cache.put(request, response.clone());
      return response;
    })
    .catch(() => undefined);
  if (cached) return cached;
  const response = await network;
  if (response) return response;
  return new Response('', { status: 504, statusText: 'Offline' });
}
